a("|---|---|---|---|---|---|---|---|")
for r in R:
    cells = " | ".join(f"{pc(r['over'][str(l)],0)} ({pc(r['over_alt'][str(l)],0)})" for l in [19.5,20.5,21.5,22.5,23.5,24.5,25.5])
    a(f"| {r['A']} v {r['B']} | {cells} |")
a("")
a("**Games won per player (mean / median; P(More) at lines).** Lookup for any Dabble/Underdog 'games won' line (none were found for today).")
a("")
